import { test, expect } from '@playwright/test';

test.describe('Reading Order - Visual Order Match', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/document');
  });

  test('should display page content in visual reading order', async ({ page }) => {
    // Verify the first element is visible and in the correct order
    const firstParagraph = page.getByRole('paragraph', { name: /first paragraph/i });
    await expect(firstParagraph).toBeVisible();

    // Verify the second element is visible and in the correct order
    const secondParagraph = page.getByRole('paragraph', { name: /second paragraph/i });
    await expect(secondParagraph).toBeVisible();

    // Verify the third element is visible and in the correct order
    const thirdParagraph = page.getByRole('paragraph', { name: /third paragraph/i });
    await expect(thirdParagraph).toBeVisible();

    // Verify the fourth element is visible and in the correct order
    const fourthParagraph = page.getByRole('paragraph', { name: /fourth paragraph/i });
    await expect(fourthParagraph).toBeVisible();

    // Verify the page has a total of 4 paragraphs
    const allParagraphs = page.getByRole('paragraph');
    const paragraphCount = await allParagraphs.count();
    expect(paragraphCount).toBe(4);
  });

  test('should handle complex layout with correct reading order', async ({ page }) => {
    // Verify the first section is visible
    const firstSection = page.getByRole('region', { name: /introduction/i });
    await expect(firstSection).toBeVisible();

    // Verify the second section is visible
    const secondSection = page.getByRole('region', { name: /main content/i });
    await expect(secondSection).toBeVisible();

    // Verify the third section is visible
    const thirdSection = page.getByRole('region', { name: /conclusion/i });
    await expect(thirdSection).toBeVisible();

    // Verify the navigation menu is visible and accessible
    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();

    // Verify the main content area is not before the navigation
    const mainContent = page.getByRole('main');
    const navBoundingBox = await navMenu.boundingBox();
    const mainBoundingBox = await mainContent.boundingBox();

    expect(navBoundingBox.y).toBeLessThan(mainBoundingBox.y);
  });
});
